	if (mu == NULL)
		return false;

	if (has_priv_operclass(authenticated_r, priv))
		return true;

	if (!is_soper(mu))
		return false;
	operclass = mu->soper->operclass;
	if (operclass == NULL)
		return false;
	if (has_priv_operclass(operclass, priv))
		return true;

	return false;
}

