bool has_priv_user(user_t *u, const char *priv) /* <=== has_priv_user */ 
{
	operclass_t *operclass;

	if (priv == NULL)
		return true;

	if (u == NULL)
		return false;

	if (has_priv_operclass(user_r, priv))
		return true;

	if (is_ircop(u) && has_priv_operclass(ircop_r, priv))
		return true;

	if (u->myuser != NULL && has_priv_operclass(authenticated_r, priv))
		return true;

	if (u->myuser && is_soper(u->myuser))
	{
		operclass = u->myuser->soper->operclass;
		if (operclass == NULL)
			return false;
		if (operclass->flags & OPERCLASS_NEEDOPER && !is_ircop(u))
			return false;
		if (u->myuser->soper->password != NULL && !(u->flags & UF_SOPER_PASS))
			return false;
		if (has_priv_operclass(operclass, priv))
			return true;
	}

	return false;
}

void object_unref(void *obj) /* <=== object_unref */ 
{
	return_if_fail(obj != NULL);
	return_if_fail(object(obj)->refcount >= -1);

	if (object(obj)->refcount == -1)
		return;
	else if (object(obj)->refcount > 0)
	{
		object_sink_ref(obj);
		if (object(obj)->refcount == 0)
			object_dispose(obj);
	}
}

chanacs_t *chanacs_add(mychan_t *mychan, myentity_t *mt, unsigned int level, time_t ts, myentity_t *setter) /* <=== chanacs_add */ 
{
	chanacs_t *ca;

	return_val_if_fail(mychan != NULL && mt != NULL, NULL);

	if (*mychan->name != '#')
	{
		slog(LG_DEBUG, "chanacs_add(): got non #channel: %s", mychan->name);
		return NULL;
	}

	if (!(runflags & RF_STARTING))
		slog(LG_DEBUG, "chanacs_add(): %s -> %s", mychan->name, mt->name);

	ca = mowgli_heap_alloc(chanacs_heap);

	object_init(object(ca), mt->name, (destructor_t) chanacs_delete);
	ca->mychan = mychan;
	ca->entity = isdynamic(mt) ? object_ref(mt) : mt;
	ca->host = NULL;
	ca->level = level & ca_all;
	ca->tmodified = ts;
	ca->setter = setter != NULL ? strshare_ref(setter->name) : NULL;

	mowgli_node_add(ca, &ca->cnode, &mychan->chanacs);
	mowgli_node_add(ca, &ca->unode, &mt->chanacs);

	cnt.chanacs++;

	return ca;
}

void object_dispose(void *object) /* <=== object_dispose */ 
{
	object_t *obj;
	mowgli_patricia_t *privatedata, *metadata;

	return_if_fail(object != NULL);
	obj = object(object);

	/* we shouldn't be disposing an object more than once in it's
	 * lifecycle.  so do a soft assert and get out if that's the case.
	 *    --nenolod
	 */
	return_if_fail(obj->refcount != -1);

	/* set refcount to -1 to ensure that object_unref() doesn't cause a loop */
	obj->refcount = -1;

	privatedata = obj->privatedata;
	metadata = obj->metadata;

#ifdef OBJECT_DEBUG
	mowgli_node_delete(&obj->dnode, &object_list);
#endif

	if (obj->destructor != NULL)
		obj->destructor(obj);
	else
	{
		metadata_delete_all(obj);
		free(obj);
	}

	if (privatedata != NULL)
		mowgli_patricia_destroy(privatedata, NULL, NULL);

	if (metadata != NULL)
		mowgli_patricia_destroy(metadata, NULL, NULL);
}

